import {BIO_STORE,available,validRecord,createPasskey,wrapVaultKey,openWithPasskey,errorMessage} from './biometric.js';
let bioAvailable=false,bioStage=0,bioMaster='',bioPending=null,bioController=null,bioActive=false;
import {derive,seal,open,openWithKey} from './crypto.js';
import {remember,recall,forget} from './session.js';
import {accountScope,LOCAL_STORE} from './account.js';
import * as cloud from './firebase.js';
const $=id=>document.getElementById(id),defaults=['Pessoal','Trabalho','Finanças','Redes sociais','Outros'];
let STORE=LOCAL_STORE,bioStore=BIO_STORE,user=null,cloudReady=false,cloudRevision=null,accountEpoch=0,initializing=true;
let key=null,salt=null,items=[],category='',editing=null,revision=null,session=0,busy=false,lastActivity=Date.now(),toastTimer;
function notify(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000)}
function gate(){try{const exists=!!localStorage.getItem(STORE);$('gate-title').textContent=exists?'Bem-vindo de volta':'Crie seu cofre';$('gate-desc').textContent=exists?'Digite sua senha mestra para abrir seus acessos.':'Escolha uma senha mestra para proteger seus acessos.';$('gate-submit').textContent=exists?'Desbloquear cofre':'Criar cofre';$('confirm-label').hidden=exists;$('confirm-master').required=!exists;$('master').minLength=exists?1:12;$('master').autocomplete=exists?'current-password':'new-password';refreshBio();syncRemember();}catch{$('gate-error').textContent='O armazenamento está indisponível neste navegador.';$('gate-submit').disabled=true}}
function lock(message,revoke=true){session++;if(revoke){void forget(STORE).catch(()=>{});try{localStorage.setItem(STORE+':locked',crypto.randomUUID())}catch{}}bioController?.abort();bioMaster='';bioPending=null;bioStage=0;bioActive=false;document.body.classList.remove('authenticating');$('bio-form').reset();key=null;salt=null;items=[];revision=null;editing=null;$('workspace').hidden=true;$('gate').hidden=false;$('entries').replaceChildren();$('categories').replaceChildren();$('search').value='';$('category-title').textContent='Todas as senhas';$('result-count').textContent='';$('total').textContent='0';$('category-options').replaceChildren();category='';document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('entry-form').reset();$('restore-form').reset();$('gate-form').reset();gate();if(message)notify(message)}
async function unlocked(data,raw){key=data.key;salt=data.salt;items=data.items;revision=raw;lastActivity=Date.now();$('gate-form').reset();$('gate').hidden=true;$('workspace').hidden=false;refreshBio();render();updateAccountUI();await saveSession()}
async function persist(next){if(!key||busy)throw Error('Aguarde e tente novamente.');busy=true;const current=session,scope=STORE,account=user?.uid;try{const blob=JSON.stringify(await seal(next,key,salt));if(current!==session||!key)throw Error('Cofre bloqueado. Abra novamente.');if(localStorage.getItem(STORE)!==revision){lock();throw Error('O cofre mudou em outra aba. Abra novamente.')}if(account){await cloud.push(account,cloudRevision,blob);if(current!==session||STORE!==scope)return;cloudRevision=blob}localStorage.setItem(STORE,blob);revision=blob;items=next;render();$('sync-status').textContent=account?'Sincronizado com sua conta':'Salvo neste navegador'}finally{busy=false}}
$('gate-form').addEventListener('submit',async e=>{e.preventDefault();$('gate-error').textContent='';$('gate-submit').disabled=true;const current=session;try{if(initializing)throw Error('Aguarde a verificação da conta.');if(!crypto.subtle)throw Error('Abra o site por HTTPS para usar a criptografia.');const raw=localStorage.getItem(STORE),password=$('master').value;let data;if(raw){try{data=await open(JSON.parse(raw),password)}catch{throw Error('Senha mestra incorreta ou cofre danificado.')}}else{if(password.length<12)throw Error('Use pelo menos 12 caracteres.');if(password!==$('confirm-master').value)throw Error('As senhas não são iguais.');const s=crypto.getRandomValues(new Uint8Array(16));data={key:await derive(password,s),salt:s,items:[]}}if(current!==session)return;if(localStorage.getItem(STORE)!==raw)throw Error('O cofre mudou em outra aba. Tente novamente.');const stored=raw||JSON.stringify(await seal([],data.key,data.salt));if(current!==session)return;if(!raw){if(localStorage.getItem(STORE)!==null)throw Error('Um cofre já foi criado em outra aba.');if(user){await cloud.push(user.uid,cloudRevision,stored);if(current!==session)return;cloudRevision=stored}localStorage.setItem(STORE,stored)}await unlocked(data,stored)}catch(err){$('gate-error').textContent=err.message}finally{$('gate-submit').disabled=false}});
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function button(text,handler,cls){const b=el('button',cls,text);b.type='button';b.addEventListener('click',handler);return b}
function render(){const cats=[...new Set([...defaults,...items.map(e=>e.category)])];$('categories').replaceChildren();for(const c of ['',...cats]){const b=button(c||'Todas as senhas',()=>{category=c;render()},category===c?'active':'');b.append(el('span','',String(c?items.filter(e=>e.category===c).length:items.length)));$('categories').append(b)}$('category-options').replaceChildren(...cats.map(c=>{const o=document.createElement('option');o.value=c;return o}));$('total').textContent=items.length;$('category-title').textContent=category||'Todas as senhas';const q=$('search').value.toLocaleLowerCase('pt-BR').trim();const shown=items.filter(e=>(!category||e.category===category)&&[e.title,e.username,e.url].some(v=>v.toLocaleLowerCase('pt-BR').includes(q))).sort((a,b)=>a.title.localeCompare(b.title,'pt-BR'));$('result-count').textContent=`${shown.length} ${shown.length===1?'acesso':'acessos'}`;$('entries').replaceChildren();if(!shown.length){const n=el('div','empty');n.append(el('div','empty-icon','◇'),el('h3','',items.length?'Nenhuma senha encontrada':'Seu cofre começa aqui'),el('p','',items.length?'Tente outra pesquisa ou escolha uma categoria diferente.':'Adicione seu primeiro acesso e deixe suas senhas organizadas.'),button(items.length?'Limpar filtros':'+ Adicionar primeira senha',()=>{if(items.length){category='';$('search').value='';render()}else edit()},'primary'));$('entries').append(n)}for(const e of shown){const card=el('article','entry'),head=el('div','entry-heading'),titles=el('div');titles.append(el('h3','',e.title),el('small','',e.category));head.append(el('div','entry-avatar',e.title.slice(0,1).toUpperCase()),titles);const secret=el('div','secret'),code=el('code','','••••••••••••');let visible=false,timer;const show=button('Mostrar',()=>{visible=!visible;clearTimeout(timer);code.textContent=visible?e.password:'••••••••••••';show.textContent=visible?'Ocultar':'Mostrar';if(visible)timer=setTimeout(()=>{visible=false;code.textContent='••••••••••••';show.textContent='Mostrar'},15000)});secret.append(code,show);const actions=el('div','entry-actions');actions.append(button('Copiar',async()=>{try{await navigator.clipboard.writeText(e.password);notify('Senha copiada. Limpe a área de transferência após usar.')}catch{notify('Não foi possível copiar. Use Mostrar para copiar manualmente.')}}),button('Editar',()=>edit(e)),button('Excluir',async()=>{if(!confirm(`Excluir a senha de ${e.title}?`))return;try{await persist(items.filter(v=>v.id!==e.id));notify('Senha excluída.')}catch(err){notify(err.message)}},'delete'));card.append(head,el('p','entry-user',e.username||'Sem usuário'),secret);if(e.url)card.append(el('p','entry-notes',e.url));if(e.notes)card.append(el('p','entry-notes',e.notes));card.append(actions);$('entries').append(card)}}
function edit(entry){editing=entry?.id||null;$('entry-form').reset();$('entry-error').textContent='';$('editor-title').textContent=entry?'Editar senha':'Nova senha';for(const name of ['title','username','password','url','category','notes'])$('entry-form').elements[name].value=entry?.[name]||(name==='category'?(category||'Pessoal'):'');$('entry-form').elements.password.type='password';$('toggle-entry').textContent='Mostrar';$('editor').showModal()}
$('entry-form').addEventListener('submit',async e=>{e.preventDefault();$('entry-error').textContent='';$('save-entry').disabled=true;try{const f=$('entry-form').elements;const entry={id:editing||crypto.randomUUID(),title:f.title.value.trim(),username:f.username.value.trim(),password:f.password.value,url:f.url.value.trim(),category:f.category.value.trim(),notes:f.notes.value.trim()};if(!entry.title||!entry.category)throw Error('Preencha nome e categoria.');await persist(editing?items.map(v=>v.id===editing?entry:v):[...items,entry]);$('editor').close();$('entry-form').reset();notify(user?'Senha criptografada salva na sua conta.':'Senha salva neste navegador.')}catch(err){$('entry-error').textContent=err.message}finally{$('save-entry').disabled=false}});
$('toggle-entry').onclick=()=>{const p=$('entry-form').elements.password;p.type=p.type==='password'?'text':'password';$('toggle-entry').textContent=p.type==='password'?'Mostrar':'Ocultar'};
$('editor').addEventListener('close',()=>$('entry-form').reset());$('close-editor').onclick=()=>$('editor').close();$('add').onclick=()=>edit();$('search').oninput=render;$('lock').onclick=()=>lock('Cofre bloqueado. Digite a senha para reabrir.');
$('export').onclick=()=>{try{const raw=localStorage.getItem(STORE);if(!raw)throw Error();const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`cofre-local-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup criptografado exportado.')}catch{notify('Não foi possível exportar.')}};
function restoreDialog(){$('restore-form').reset();$('restore-error').textContent='';$('restore-dialog').showModal()}
$('restore').onclick=restoreDialog;$('restore-gate').onclick=restoreDialog;$('close-restore').onclick=()=>$('restore-dialog').close();$('restore-dialog').addEventListener('close',()=>$('restore-form').reset());
$('restore-form').onsubmit=async e=>{e.preventDefault();$('restore-error').textContent='';$('restore-submit').disabled=true;const current=session;try{const before=localStorage.getItem(STORE),file=$('backup-file').files[0];if(!file||file.size>10000000)throw Error('Escolha um backup de até 10 MB.');const data=JSON.parse(await file.text());let decoded;try{decoded=await open(data,$('backup-master').value)}catch{throw Error('Backup inválido ou senha mestra incorreta.')}if(current!==session)throw Error('A sessão mudou. Tente novamente.');if(busy||localStorage.getItem(STORE)!==before)throw Error('O cofre mudou. Tente novamente.');if(before&&!confirm('Substituir o cofre atual pelo backup validado?'))return;const raw=JSON.stringify(data);if(user){await cloud.push(user.uid,cloudRevision,raw);if(current!==session)throw Error('A sessão mudou.');cloudRevision=raw}localStorage.setItem(STORE,raw);localStorage.removeItem(bioStore);session++;await unlocked(decoded,raw);$('restore-dialog').close();notify('Backup restaurado.')}catch(err){$('restore-error').textContent=err.message||'Não foi possível restaurar.'}finally{$('restore-submit').disabled=false}};
for(const event of ['pointerdown','keydown','scroll'])document.addEventListener(event,()=>{if(key&&!keepOpen()&&Date.now()-lastActivity>=300000){lock('Cofre bloqueado por inatividade.');return}lastActivity=Date.now()},{passive:true,capture:true});
setInterval(()=>{if(key&&!keepOpen()&&Date.now()-lastActivity>=300000)lock('Cofre bloqueado por inatividade.')},1000);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&key&&!bioActive&&!keepOpen())lock()});
window.addEventListener('pagehide',()=>{if(!keepOpen())lock()});
window.addEventListener('pageshow',()=>{if(key&&!keepOpen())lock()});
window.addEventListener('storage',e=>{if(e.key===STORE||e.key===bioStore||e.key===STORE+':locked'||e.key===null){lock('O cofre mudou em outra aba. Abra novamente.',false)}});

function bioRecord(){try{const record=JSON.parse(localStorage.getItem(bioStore)),vault=JSON.parse(localStorage.getItem(STORE));return validRecord(record,vault)?record:null}catch{return null}}
function refreshBio(){const enabled=!!bioRecord();$('bio-unlock').hidden=!enabled||!bioAvailable;$('bio-gate-note').hidden=!enabled||!bioAvailable;$('bio-settings').textContent=enabled?'Face ID ativado':'Ativar Face ID / biometria'}
async function nativePrompt(action){bioActive=true;bioController=new AbortController();document.body.classList.add('authenticating');try{return await action(bioController.signal)}finally{bioActive=false;bioController=null;document.body.classList.remove('authenticating');if(document.hidden&&key&&!keepOpen())lock()}}
$('bio-settings').onclick=()=>{bioMaster='';bioPending=null;bioStage=0;$('bio-form').reset();$('bio-error').textContent='';$('bio-status').textContent=bioRecord()?'Face ID ativado neste navegador. Você pode desativar ou cadastrar outra chave.':'';$('bio-description').textContent=bioAvailable?'No iPhone compatível, o sistema usa Face ID ou o código do aparelho. Confirme sua senha mestra para começar.':'Este navegador não oferece biometria compatível. Abra o endereço definitivo diretamente no Safari atualizado em um iPhone com Face ID.';$('bio-password-label').hidden=!bioAvailable;$('bio-password').required=bioAvailable;$('bio-next').hidden=!bioAvailable;$('bio-next').disabled=false;$('bio-next').textContent='Confirmar senha mestra';$('bio-disable').hidden=!bioRecord();$('bio-dialog').showModal()};
$('close-bio').onclick=()=>$('bio-dialog').close();
$('bio-dialog').addEventListener('close',()=>{bioController?.abort();bioMaster='';bioPending=null;bioStage=0;$('bio-form').reset()});
$('bio-form').onsubmit=async e=>{e.preventDefault();const current=session,raw=revision;$('bio-error').textContent='';$('bio-next').disabled=true;try{if(!key||!raw||localStorage.getItem(STORE)!==raw)throw Error('Abra o cofre novamente.');const vault=JSON.parse(raw);if(bioStage===0){const password=$('bio-password').value;try{await open(vault,password)}catch{throw Error('Senha mestra incorreta.')}if(current!==session)return;bioMaster=password;$('bio-password').value='';$('bio-password').required=false;$('bio-password-label').hidden=true;bioStage=1;$('bio-next').textContent='Criar chave de acesso';$('bio-status').textContent='Confirme a criação da chave na próxima janela do sistema.'}else if(bioStage===1){const pending=await nativePrompt(signal=>createPasskey(vault,signal));if(current!==session)return;bioPending=pending;bioStage=2;$('bio-next').textContent='Confirmar Face ID';$('bio-status').textContent='A chave foi criada. Confirme mais uma vez para ativar o desbloqueio do cofre.'}else{const record=await nativePrompt(signal=>wrapVaultKey(bioPending,bioMaster,signal));if(current!==session)return;if(localStorage.getItem(STORE)!==raw)throw Error('O cofre mudou. Feche esta janela e tente novamente.');localStorage.setItem(bioStore,JSON.stringify(record));bioMaster='';bioPending=null;$('bio-dialog').close();refreshBio();notify('Face ID ativado. Bloqueie o cofre para experimentar.')}}catch(err){$('bio-error').textContent=errorMessage(err)}finally{$('bio-next').disabled=false}};
$('bio-disable').onclick=()=>{try{localStorage.removeItem(bioStore);$('bio-dialog').close();refreshBio();notify('Face ID desativado neste navegador. A chave pode ser removida no app Senhas da Apple.')}catch{notify('Não foi possível desativar. Tente novamente.')}};
$('bio-unlock').onclick=async()=>{const current=session;$('gate-error').textContent='';$('bio-unlock').disabled=true;try{const raw=localStorage.getItem(STORE),record=bioRecord();if(!raw||!record)throw Error('Use a senha mestra para ativar o Face ID.');const data=await nativePrompt(signal=>openWithPasskey(record,JSON.parse(raw),signal));if(current!==session)return;if(document.hidden)throw Error('Volte ao cofre e tente novamente.');if(localStorage.getItem(STORE)!==raw)throw Error('O cofre mudou em outra aba. Tente novamente.');await unlocked(data,raw)}catch(err){$('gate-error').textContent=errorMessage(err)}finally{$('bio-unlock').disabled=false}};
available().then(value=>{bioAvailable=value;refreshBio()});

function keepOpen(){try{return localStorage.getItem(STORE+':remember')!=='false'}catch{return false}}
function syncRemember(){const enabled=keepOpen();$('remember-gate').checked=enabled;$('remember-workspace').checked=enabled;$('session-note').textContent=enabled?'Este aparelho pode reabrir o cofre sem pedir a senha. Bloqueie para encerrar.':'O cofre bloqueia ao sair da aba ou após 5 minutos sem atividade.'}
async function saveSession(){syncRemember();if(!key)return;try{if(keepOpen())await remember(STORE,key,salt,localStorage.getItem(STORE+':locked'));else await forget(STORE)}catch{notify('O navegador não permitiu lembrar o acesso. A senha será pedida ao reabrir.')}}
for(const id of ['remember-gate','remember-workspace'])$(id).onchange=async()=>{try{localStorage.setItem(STORE+':remember',String($(id).checked));await saveSession();syncRemember()}catch{notify('Não foi possível alterar a preferência.')}};
async function restoreSession(){const current=session,scope=STORE;syncRemember();if(!keepOpen())return;try{const saved=await recall(scope),raw=localStorage.getItem(scope);if(!saved||!raw||current!==session||scope!==STORE)return;if(saved.generation!==localStorage.getItem(scope+':locked')){await forget(scope);return}const envelope=JSON.parse(raw),salt64=btoa(String.fromCharCode(...saved.salt));if(salt64!==envelope.salt){await forget(scope);return}const data=await openWithKey(envelope,saved.key);if(current!==session||scope!==STORE||localStorage.getItem(scope)!==raw)return;await unlocked(data,raw)}catch{void forget(scope).catch(()=>{})}}
function updateAccountUI(){
 $('account-name').textContent=user?(user.email||user.displayName||'Minha conta Google'):'Cofre deste navegador';
 $('account-action').textContent=user?'Sair da conta Google':'Entrar com Google';$('account-action').disabled=!cloudReady&&!user;
 $('gate-account').hidden=!user;$('gate-account-name').textContent=user?(user.email||user.displayName||'Minha conta Google'):'';
 $('google-login').hidden=!!user;$('google-login').disabled=!cloudReady;
 $('google-status').textContent=user?'Conta conectada. Seu cofre é separado das outras contas.':cloudReady?'Use sua conta Google para acessar seu cofre em outros aparelhos.':'Login Google aguardando configuração do Firebase. Seu cofre local continua disponível.';
 $('sync-status').textContent=user?'Cofre criptografado da sua conta':'Armazenamento local';
 $('storage-note').textContent=user?'Somente o conteúdo criptografado vai para sua conta. A senha mestra abre o cofre no primeiro acesso de cada aparelho.':'Seu cofre local permanece neste navegador e endereço. Exporte um backup antes de limpar seus dados.';
 $('import-local').hidden=!user||!!localStorage.getItem(STORE)||!localStorage.getItem(LOCAL_STORE);syncRemember();
}
async function selectAccount(next){
 const epoch=++accountEpoch;const changed=(user?.uid||null)!==(next?.uid||null);
 if(changed)lock(undefined,true);else lock(undefined,false);
 user=next;const scope=accountScope(user?.uid);STORE=scope.store;bioStore=scope.bio;cloudRevision=null;initializing=true;
 $('gate-submit').disabled=true;updateAccountUI();gate();
 try{if(user){const uid=user.uid;const remote=await cloud.pull(uid);if(epoch!==accountEpoch)return;cloudRevision=remote;if(remote)localStorage.setItem(STORE,remote);else localStorage.removeItem(STORE)}
 if(epoch!==accountEpoch)return;initializing=false;gate();await restoreSession();
 }catch(error){if(epoch===accountEpoch){$('gate-error').textContent=cloud.loginError(error)+' Recarregue para tentar novamente.';}}finally{if(epoch===accountEpoch){$('gate-submit').disabled=initializing;updateAccountUI()}}
}
async function googleLogin(){if(!cloudReady){notify('Login Google aguardando configuração do Firebase.');return}$('google-login').disabled=true;try{await cloud.login()}catch(error){notify(cloud.loginError(error))}finally{$('google-login').disabled=false}}
$('google-login').onclick=googleLogin;
async function googleLogout(){lock('Acesso encerrado neste aparelho.');try{await cloud.logout()}catch(error){notify(cloud.loginError(error))}}
$('google-logout').onclick=googleLogout;$('account-action').onclick=()=>user?googleLogout():googleLogin();
$('import-local').onclick=async()=>{
 const current=session,uid=user?.uid;if(!uid||localStorage.getItem(STORE))return;
 $('gate-error').textContent='';$('import-local').disabled=true;
 try{const raw=localStorage.getItem(LOCAL_STORE);if(!raw)throw Error('Nenhum cofre local encontrado.');const password=$('master').value;if(!password)throw Error('Digite a senha mestra do seu cofre local no campo acima para importar.');let data;try{data=await open(JSON.parse(raw),password)}catch{throw Error('Senha mestra do cofre local incorreta.')}if(current!==session||user?.uid!==uid)return;await cloud.push(uid,null,raw);if(current!==session||user?.uid!==uid)return;cloudRevision=raw;localStorage.setItem(STORE,raw);await unlocked(data,raw);notify('Cofre importado. A cópia local foi preservada.')}catch(error){$('gate-error').textContent=cloud.loginError(error)}finally{$('import-local').disabled=false}
};
gate();$('gate-submit').disabled=true;
cloud.connect(selectAccount).then(async enabled=>{cloudReady=enabled;if(!enabled)await selectAccount(null);updateAccountUI()}).catch(async error=>{cloudReady=false;await selectAccount(null);$('google-status').textContent='Google indisponível. Seu cofre local continua disponível.';notify(cloud.loginError(error))});
